-- 所有租户表启用强制 RLS；没有事务局部 tenant_id 时默认不可读写。
ALTER TABLE "TenantCompanies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TenantCompanies" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON "TenantCompanies" USING ("TenantId" = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("TenantId" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
